'use strict';
// Twenty activities use seven short courses; a course is a flexible route, not a prerequisite.
for(const word of ['jam','bun','egg','fig'])if(!readingWords[word])readingWords[word]={word,tiles:[...word],picture:word,sounds:'Model the taught sounds and blend together.'};
const wordQuestGames=[
 ['word-change-lab','The one-letter change lab','change',['cap>cat','map>mop','pin>pen','dog>log'],'Change a single spelling and reread the resulting word to connect a sound change with a change in meaning.','May support children who overlook middle or final spellings, including some children with dyslexia.','Model both words and their sounds first. The destination picture is a spelling cue, so completion is not independent reading.'],
 ['picture-crosswords','The tiny picture crossword','crossword',['cat|map','dog|log','pen|net','pig|pin'],'Build two intersecting short words from picture clues, attending to every spelling and the shared vowel.','May support children who need explicit practice keeping all letters in order.','Name both pictures; supply a printed word model if needed. Fill one arm at a time; keyboard and tap require no tracing.'],
 ['word-search-garden','The hidden-word garden','search',['cat','dog','cup','pig'],'Find a whole short word in a small letter garden, following its letters in order.','May help organise practice for children who lose their place in print or skip letters. This is not a treatment for visual or reading disorders.','Read the picture name and model its spellings. The target is horizontal or vertical and its first letter is marked; no diagonal tracking or speed is required.'],
 ['word-picture-pairs','The word-and-picture quilt','pairs',['cat|cup','dog|bag','pig|pen','hat|mop'],'Join printed words with their picture meanings to complete a little quilt.','May support children with decoding and language difficulties when vocabulary and print both need practice.','All cards stay face up; memory is not a requirement. Model unfamiliar vocabulary, then blend the words.'],
 ['word-sort-workshop','Animal hotel or object store?','sort',['cat|dog|cup|hat','pig|fish|bag|mop','dog|cat|pen|bed','fish|pig|cap|mug'],'Read a word card, work out its meaning, and send it to the animal hotel or object store.','May support language difficulties with word meanings and categories alongside decoding practice.','Name the two categories and demonstrate one card. Read untaught fish spellings, including sh. Categorising is a separate demand from decoding.'],
 ['missing-picture-inventory','The missing-picture detective','inventory',['cat|cup|bag','dog|hat|pen','pig|mop|cap','bed|net|mug'],'Compare a printed inventory with visible picture cards and add the one missing picture.','May support children who need help checking a short list systematically, including some children with attention or developmental difficulties.','Read one inventory word at a time and point to its picture. The list stays visible; working memory is not tested.'],
 ['mini-comic-director','You direct the tiny comic','comic',['cat-day','dog-day','cat-night','dog-night'],'Choose short written action commands to create a three-panel comic with different actions.','May support linking verbs to meaning for children with language difficulties; speech is not required.','Model sit, nap and tap before playing. Tap means tapping a drum. Any three changing actions make a story; this records shared practice, not correct decoding.'],
 ['read-paint-studio','Read it, paint it!','paint',['red hat','tan cap','red bag','red mug'],'Use a two-word instruction to choose paint and colour the named object.','May support children who read the noun but miss another word in a short message.','Teach red and tan and read both words. Paint pots also have printed names; colour naming or colour vision is not required. An adult may describe the paints.'],
 ['count-the-word','The little quantity maker','quantity',['2|cup','3|hat','2|dog','3|cat'],'Use a short printed instruction to create the requested collection and reread its object word.','May support understanding of a brief written direction for children with language or developmental difficulties.','The grown-up supplies the numeral and plural ending if untaught. Counting is an additional task; build the collection together if necessary.'],
 ['word-lock-safe','The picture-lock treasure safe','safe',['cat|cup|bag','dog|hat|pen','pig|cap|mop','bed|mug|net'],'Turn three word dials to match three picture locks; every setting remains visible until the safe opens.','May support children who benefit from comparing whole similar words and checking one small step at a time.','Name each picture, model reading the alternatives, and turn one dial at a time. Pointing or an adult turning the dial is welcome.'],
 ['tiny-recipe-kitchen','The tiny recipe kitchen','recipe',['bun|jam','bun|egg','jam|fig','egg|bun'],'Follow a visible two-step word recipe to arrange food picture cards on a recipe board.','May support children with language or attention difficulties who need short, meaningful sequences kept visible.','Read the words together and name unfamiliar foods. This makes picture recipes, not real cooking or feeding advice. Supply the first-step/next-step concept if needed.'],
 ['word-space-snip','The space-snipping machine','spaces',['red hat','tan cap','red bag','red mug'],'Insert a word boundary into a squashed two-word caption and connect it with a picture.','May support children who need explicit help noticing that print contains separate words.','Model the two-word message aloud. A printed model is available. A space separates words; it does not split a word into syllables or sounds.'],
 ['picture-word-bingo','The little picture bingo board','bingo',['cat|cup|hat|bag','dog|pen|mop|cap','pig|bed|mug|net','cat|dog|pig|fish'],'Read a two-by-two word board and mark the word for each picture card until the board is complete.','May support repeated accurate word reading in a predictable format for children who find large busy boards difficult.','Name the picture if unfamiliar, then read all spellings in the candidate word. There is no race, competition or penalty.'],
 ['word-window-mosaic','The word-window mosaic','mosaic',['cat|cap','dog|log','pin|pen','map|mop'],'Remove only labels that read the target word to uncover a picture mosaic.','May support close comparison of similar short words when a child guesses from the first letter.','There are three target labels and three near-neighbour labels. Model blending and compare the changing spelling; repeated targets are deliberate rereading practice.'],
 ['syllable-drum-bot','The one-beat, two-beat band','beats',['cup','napkin','dog','mitten'],'Give the robot one beat token for each spoken syllable, then connect the word with its picture.','May support supported syllable awareness and chunking for children with language or broader developmental difficulties.','An adult must say and model the word because there is no audio. cup and dog have one syllable; napkin and mitten have two. Count spoken beats, not letters or phonemes. No movement or sound production is required.']
].map(([id,title,quest,items,why,support,adapt])=>({id,title,quest,items,why,support,adapt,adult:adapt,mode:'quest-'+quest,theme:'workshop',wordPlay:true,extended:true,units:['a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','r','s','t','u']}));
readingGames.push(...wordQuestGames);wordPlayGames.push(...wordQuestGames);
const questCourseSpecs=[
 ['word-builders-puzzles','Build, change & find words','Attend to every spelling while changing words, building a small crossword and searching a letter garden.','Letters are skipped or their order needs explicit support.'],
 ['word-meanings-checking','Word meanings & careful checking','Match print with meaning, sort familiar categories and use a short inventory.','Decoding, vocabulary or checking a visible list needs adult support.'],
 ['playful-reading-studio','The playful reading studio','Use printed actions and short instructions to direct a comic, paint an object and build a collection.','The child needs a concrete reason to read a short word or a whole brief message.'],
 ['reading-small-plans','Read a small plan','Open word locks, follow a tiny picture recipe and separate a short caption into words.','Multi-step demands or word boundaries need smaller, visible steps.'],
 ['word-picture-challenges','Little word & picture challenges','Practise whole-word reading through a small bingo board, a mosaic and a supported syllable band.','The child benefits from predictable short activities with different ways to revisit print and meaning.']
];
for(let i=0;i<questCourseSpecs.length;i++){const[id,title,goal,need]=questCourseSpecs[i],course={id,title,goal,need,reading:true,extended:true,level:'Adult-supported early reading',props:'A grown-up, taught English spellings, familiar picture vocabulary, and usual communication and input supports',activities:wordQuestGames.slice(i*3,i*3+3).map(g=>({engine:'reading',key:g.id})),home:'Choose one familiar game word. Read it together in plain print, then use it in a real label, message or action. Supply unfamiliar spellings.',notice:['Which spellings or meanings need modelling','Whether the extra puzzle or sequencing task needs help','Which input, display or adult support makes participation easier']};readingCourses.push(course);readingSkill.courses.push(course);wordPlayCourses.push(course);for(const section of parentSupportSections)if(['dyslexia','language','development','speech','motor','autism','attention'].includes(section.id))section.readingCourses=[...new Set([...(section.readingCourses||[]),id])];}
const initialSupport=[
 ['May support children who need to connect a decoded word with meaning, including some children with dyslexia or language difficulties.','Model one word first. Two still picture-fish keep the board quieter; a direct tap avoids aiming with a net.'],
 ['May support children who need a short visible list and a useful reason to read, including some children with attention or language difficulties.','Keep the list visible and read one word at a time. Pointing plus adult-entered choices is welcome.'],
 ['May support checking the whole word when similar spellings are confused.','Start with two labels. The pictures and all labels remain visible; there is no memory test.'],
 ['May support children who need short linked reading steps with a visible record of what they have completed.','Pause between links, model each new word, and keep the smaller choice set if useful.'],
 ['May support a child ready for longer words who needs explicit help joining spoken syllable chunks.','Model the whole word and each chunk. A printed model stays available; this is not a test of unaided reading.']
];wordPlayGames.slice(0,5).forEach((g,i)=>{[g.support,g.adapt]=initialSupport[i];});

const questUnits={change:['a','c','p','t','m','o','i','n','e','d','g','l'],crossword:['c','a','t','m','p','d','o','g','l','e','n','i'],search:['c','a','t','d','o','g','u','p','i'],pairs:['c','a','t','u','p','d','o','g','b','i','e','n','h','m'],sort:['c','a','t','d','o','g','u','p','h','i','f','sh','b','m','e','n'],inventory:['c','a','t','u','p','b','g','d','o','h','e','n','i','m'],comic:['s','i','t','n','a','p'],paint:['r','e','d','t','a','n','h','c','p','b','g','m','u'],quantity:['c','u','p','s','h','a','t','d','o','g'],safe:['c','a','t','u','p','b','g','d','o','h','e','n','i','m'],recipe:['b','u','n','j','a','m','e','gg','f','i','g'],spaces:['r','e','d','t','a','n','h','c','p','b','g','m','u'],bingo:['c','a','t','u','p','h','b','g','d','o','e','n','m','i','f','sh'],mosaic:['c','a','t','p','d','o','g','l','i','n','e','m'],beats:['c','u','p','n','a','k','i','d','o','g','m','tt','e']};
for(const g of wordQuestGames)g.units=questUnits[g.quest];
readingWords.egg.tiles=['e','gg'];readingWords.egg.sounds='/e/ /g/';
wordQuestGames.find(g=>g.quest==='recipe').adult+=' In egg, gg represents one /g/ sound; supply this spelling if untaught.';
